function index_base():string{$configured=(string)env('APP_URL','');$path=$configured!==''?(string)(parse_url($configured,PHP_URL_PATH)??''):'';if($path===''||$path==='/'){$script=(string)($_SERVER['SCRIPT_NAME']??'');$dir=str_replace('\\','/',dirname($script));$path=$dir==='/'||$dir==='.'?'':$dir;}return rtrim($path,'/');}
function index_url(string $path=''):string{$base=index_base();if($path==='')return $base!==''?$base.'/':'/';if(!str_starts_with($path,'/'))$path='/'.$path;return$base.$path;}
function auth_page(string$title,string$body):never{?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#241940"><title><?= Security::e($title) ?> — EventMenu Premium</title><link rel="stylesheet" href="<?= Security::e(index_url('/assets/app.css')) ?>?v=92legacy-login"><style>body.auth-page{display:block;padding:0;background:#161121}.legacy-login-shell{min-height:100vh;display:grid;grid-template-columns:minmax(360px,520px) 1fr;background:#161121}.legacy-login-panel{display:grid;place-items:center;padding:34px;background:linear-gradient(160deg,#171222,#23183c)}.legacy-login-card{width:min(410px,100%);color:#fff}.legacy-login-brand{display:flex;align-items:center;gap:12px;margin-bottom:44px}.legacy-login-mark{width:48px;height:48px;border-radius:15px;background:linear-gradient(135deg,#7e60ff,#5936ea);display:grid;place-items:center;font-weight:950;box-shadow:0 12px 30px #6d4aff55}.legacy-login-brand strong{font-size:21px;letter-spacing:-.5px}.legacy-login-brand span{display:block;color:#a994ff;font-size:10px;font-weight:900;letter-spacing:.18em;margin-top:4px}.legacy-login-card h1{font-size:31px;margin:0 0 8px}.legacy-login-card>.muted,.legacy-login-card form~p{color:#aaa2ba}.legacy-login-card label{color:#c3bbd2}.legacy-login-card input{background:#211a31;border-color:#403651;color:#fff}.legacy-login-card input:focus{border-color:#8b71ff;box-shadow:0 0 0 4px #6d4aff25}.legacy-login-card .primary{width:100%;margin-top:4px;min-height:49px}.legacy-login-card a{color:#a992ff}.legacy-login-visual{position:relative;overflow:hidden;background:radial-gradient(circle at 68% 20%,#8a5dff66 0 8%,transparent 27%),radial-gradient(circle at 30% 82%,#ff4f9d44 0 7%,transparent 28%),linear-gradient(135deg,#120d1d,#2b1744 55%,#120f21)}.legacy-login-visual:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(115deg,transparent 0 90px,#ffffff08 91px 93px)}.legacy-login-stage{position:absolute;left:10%;right:10%;bottom:12%;color:#fff;z-index:2}.legacy-login-stage small{display:block;color:#c5b7e2;text-transform:uppercase;letter-spacing:.2em;font-weight:900}.legacy-login-stage h2{font-size:clamp(38px,5vw,70px);line-height:.98;max-width:760px;margin:12px 0}.legacy-login-stage p{max-width:620px;color:#c6bfd0;font-size:15px}.legacy-login-light{position:absolute;width:5px;height:75%;top:-10%;background:linear-gradient(#fff0,#fff9,#fff0);filter:blur(2px);transform-origin:top}.l1{left:25%;transform:rotate(24deg)}.l2{left:48%;transform:rotate(-17deg)}.l3{left:72%;transform:rotate(12deg)}@media(max-width:860px){.legacy-login-shell{grid-template-columns:1fr}.legacy-login-visual{display:none}.legacy-login-panel{padding:25px 18px}.legacy-login-brand{margin-bottom:34px}}</style></head><body class="auth-page"><div class="legacy-login-shell"><section class="legacy-login-panel"><main class="legacy-login-card"><div class="legacy-login-brand"><div class="legacy-login-mark">EM</div><div><strong>EVENTMENU</strong><span>PREMIUM</span></div></div><?= $body ?><p style="margin-top:34px;font-size:11px">© <?= date('Y') ?> EventMenu Premium</p></main></section><aside class="legacy-login-visual" aria-hidden="true"><i class="legacy-login-light l1"></i><i class="legacy-login-light l2"></i><i class="legacy-login-light l3"></i><div class="legacy-login-stage"><small>Sistema completo para sua operação</small><h2>Eventos, cardápio e vendas em um só lugar.</h2><p>Gerencie ingressos, pedidos, delivery, salão, caixa e equipe com uma experiência integrada.</p></div></aside></div></body></html><?php exit;}

$route=(string)($_GET['route']??'');
try{$pdo=Database::connection();}catch(Throwable $e){http_response_code(503);exit('<h1>EventMenu Premium</h1><p>Banco ainda não configurado. Acesse <a href="'.htmlspecialchars(index_url('/install.php'),ENT_QUOTES,'UTF-8').'">o instalador</a>.</p>');}

if($route==='forgot-password'){
    $message=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Security::validateCsrf($_POST['_csrf']??null))$message='Sessão expirada. Atualize a página.';else{try{(new PasswordResetService())->request((string)($_POST['email']??''));}catch(Throwable $e){error_log('[password reset] '.$e->getMessage());}$message='Se o e-mail estiver cadastrado, as instruções de redefinição serão enviadas.';}}
    ob_start();?><h1>Redefinir senha</h1><p class="muted">Informe o e-mail da sua conta.</p><?php if($message):?><div class="alert"><?= Security::e($message) ?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><label>E-mail<input type="email" name="email" required autofocus></label><button class="primary">Enviar instruções</button></form><p><a href="<?= Security::e(index_url('/?route=login')) ?>">Voltar ao login</a></p><?php auth_page('Redefinir senha',(string)ob_get_clean());
}
if($route==='reset-password'){
    $token=(string)($_GET['token']??$_POST['token']??'');$error=null;$ok=false;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada.';else try{(new PasswordResetService())->apply($token,(string)($_POST['password']??''));$ok=true;}catch(Throwable $e){$error=$e->getMessage();}}
    ob_start();?><h1>Nova senha</h1><?php if($ok):?><div class="alert ok">Senha redefinida. Todos os dispositivos de pagamento vinculados à conta foram revogados.</div><a class="button primary" href="<?= Security::e(index_url('/?route=login')) ?>">Entrar</a><?php else:?><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="token" value="<?= Security::e($token) ?>"><label>Nova senha<input type="password" name="password" minlength="10" required autocomplete="new-password"></label><button class="primary">Salvar nova senha</button></form><?php endif;?><?php auth_page('Nova senha',(string)ob_get_clean());
}
if($route==='login'){
    if(Auth::check()){header('Location: '.index_url('/?route='.Auth::homeRoute()));exit;}$error=!empty($_GET['blocked'])?'Sua sessão foi encerrada porque o usuário ou a empresa foi bloqueado.':null;
    if($_SERVER['REQUEST_METHOD']==='POST'){if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada.';elseif(Auth::attempt((string)($_POST['email']??''),(string)($_POST['password']??''))){header('Location: '.index_url('/?route='.Auth::homeRoute()));exit;}else$error='E-mail ou senha inválidos.';}
    ob_start();?><h1>Acesse sua conta</h1><p class="muted">Entre para gerenciar sua operação.</p><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><label>Email<input type="email" name="email" placeholder="seu@email.com" required autofocus autocomplete="username"></label><label>Senha<input type="password" name="password" placeholder="Sua senha" required autocomplete="current-password"></label><button class="primary">Entrar</button></form><p><a href="<?= Security::e(index_url('/?route=forgot-password')) ?>">Esqueci minha senha</a></p><?php auth_page('Entrar',(string)ob_get_clean());
}
if($route==='logout'){Auth::logout();header('Location: '.index_url('/?route=login'));exit;}
if(!Auth::check()){header('Location: '.index_url('/?route=login'));exit;}

require __DIR__.'/../app/admin_helpers.php';
if($route==='')$route=Auth::homeRoute();if(Auth::role()==='super_admin'&&!Auth::tenantId()&&$route==='dashboard')$route='superadmin';
if($route!=='legal-accept'){try{$pending=(new LegalService())->pendingForUser((int)Auth::id());if($pending){header('Location: '.index_url('/?route=legal-accept'));exit;}}catch(Throwable){}}
$routes=['superadmin'=>'superadmin.php','dashboard'=>'dashboard.php','pos'=>'pos.php','counter-orders'=>'counter_orders.php','fulfillment'=>'fulfillment.php','menu-editor'=>'menu_editor.php','products'=>'products.php','product-options'=>'product_options.php','orders'=>'orders_legacy.php','delivery'=>'delivery.php','my-deliveries'=>'my_deliveries.php','kitchen'=>'kitchen.php','restaurant'=>'restaurant.php','cash'=>'cash.php','customers'=>'customers.php','coupons'=>'coupons.php','events'=>'events.php','tickets'=>'tickets.php','guests'=>'guests.php','promoters'=>'promoters.php','payments'=>'payments.php','gateways'=>'gateways.php','users'=>'users.php','units'=>'units.php','notifications'=>'notifications.php','search'=>'search.php','export'=>'export.php','reports'=>'reports.php','audit'=>'audit.php','settings'=>'settings.php','settings-hub'=>'settings_hub.php','legal'=>'legal.php','legal-accept'=>'legal_accept.php','backup'=>'backup.php','diagnostic'=>'diagnostic.php'];
$file=$routes[$route]??null;if(!$file){http_response_code(404);em_header('Página não encontrada','');echo '<section class="card"><h2>404</h2><p>A página solicitada não existe.</p><a class="button primary" href="'.Security::e(index_url('/?route='.Auth::homeRoute())).'">Voltar</a></section>';em_footer();exit;}
try{TenantModuleService::requireRoute($route);}catch(Throwable $e){http_response_code(403);em_header('Módulo indisponível','');echo '<section class="card"><h2>Recurso desativado</h2><p>'.Security::e($e->getMessage()).'</p><p class="muted">O Super ADM pode reativar este módulo nas configurações da empresa.</p><a class="button secondary" href="'.Security::e(index_url('/?route='.Auth::homeRoute())).'">Voltar</a></section>';em_footer();exit;}
require __DIR__.'/../app/routes/'.$file;
